    const fixedDocTypeListCollapsed = ref(false);
    const fixedDocCustomTypes = reactive([]);
    let fixedDocCustomTypeSeq = 1;
    const FIXED_DOC_DEFAULT_TYPE = '診断書';
    function getFixedDocActiveTypeId() {
      return fixedDocSettingsTarget.value || FIXED_DOC_DEFAULT_TYPE;
    }
    function getFixedDocActiveDocLabel() {
      return getDocDisplayLabel(getFixedDocActiveTypeId());
    }
    const fixedDocSteps = [
      { id: 1, label: 'AI分類設定' },
      { id: 2, label: 'AI読取設定' },
      { id: 3, label: '処理ルール設定' },
      { id: 4, label: '画像処理設定' },
      { id: 5, label: '効果テスト' },
    ];
    const fixedDocTypeId = computed(() => {
      const base = getFixedDocActiveTypeId();
      let hash = 0;
      String(base).split('').forEach((ch) => {
        hash = (hash * 31 + ch.charCodeAt(0)) % 10000000000000000;
      });
      return String(2080100000000000000n + BigInt(hash)).slice(0, 19);
    });
    const FIXED_DOC_DIAGNOSIS_PREVIEW_IMAGE = 'assets/mock-diagnosis-liaj045.png';
    const FIXED_DOC_HUMAN_DOCK_PREVIEW_IMAGE = 'assets/mock-human-dock.png';
    const fixedDocPreviewImage = computed(() => (
      getFixedDocActiveTypeId() === '人間ドック'
        ? FIXED_DOC_HUMAN_DOCK_PREVIEW_IMAGE
        : isFixedDocQrCapableDocType()
          ? FIXED_DOC_DIAGNOSIS_PREVIEW_IMAGE
          : ''
    ));
    const fixedDocPreviewScale = ref(1);
    const fixedDocPreviewRotate = ref(0);
    const fixedDocPreviewPanX = ref(0);
    const fixedDocPreviewPanY = ref(0);
    const fixedDocPreviewPanning = ref(false);
    const fixedDocPreviewPanStart = reactive({ x: 0, y: 0, panX: 0, panY: 0 });
    const fixedDocPreviewTransformStyle = computed(() => ({
      transform: `translate(${fixedDocPreviewPanX.value}px, ${fixedDocPreviewPanY.value}px) scale(${fixedDocPreviewScale.value}) rotate(${fixedDocPreviewRotate.value}deg)`,
      transformOrigin: 'center center',
    }));
    function setFixedDocPreviewScale(nextScale, origin) {
      const previousScale = fixedDocPreviewScale.value;
      const scale = Math.min(3, Math.max(0.35, +nextScale.toFixed(2)));
      if (scale === previousScale) return;
      if (origin) {
        const offsetX = origin.clientX - origin.rect.left - origin.rect.width / 2 - fixedDocPreviewPanX.value;
        const offsetY = origin.clientY - origin.rect.top - origin.rect.height / 2 - fixedDocPreviewPanY.value;
        const ratio = scale / previousScale;
        fixedDocPreviewPanX.value = +(fixedDocPreviewPanX.value - offsetX * (ratio - 1)).toFixed(1);
        fixedDocPreviewPanY.value = +(fixedDocPreviewPanY.value - offsetY * (ratio - 1)).toFixed(1);
      }
      fixedDocPreviewScale.value = scale;
    }
    function fixedDocPreviewZoomIn() {
      setFixedDocPreviewScale(fixedDocPreviewScale.value + 0.15);
    }
    function fixedDocPreviewZoomOut() {
      setFixedDocPreviewScale(fixedDocPreviewScale.value - 0.15);
    }
    function fixedDocPreviewRotateLeft() {
      fixedDocPreviewRotate.value = (fixedDocPreviewRotate.value - 90 + 360) % 360;
    }
    function fixedDocPreviewRotateRight() {
      fixedDocPreviewRotate.value = (fixedDocPreviewRotate.value + 90) % 360;
    }
    function fixedDocPreviewReset() {
      fixedDocPreviewScale.value = 1;
      fixedDocPreviewRotate.value = 0;
      fixedDocPreviewPanX.value = 0;
      fixedDocPreviewPanY.value = 0;
    }
    function fixedDocPreviewFit() {
      fixedDocPreviewReset();
    }
    function onFixedDocPreviewWheel(event) {
      if (!fixedDocPreviewImage.value) return;
      const direction = event.deltaY > 0 ? -1 : 1;
      const rect = event.currentTarget.getBoundingClientRect();
      setFixedDocPreviewScale(fixedDocPreviewScale.value + direction * 0.12, {
        clientX: event.clientX,
        clientY: event.clientY,
        rect,
      });
    }
    function clampFixedDocPreviewPercent(value) {
      return Math.max(0, Math.min(100, value));
    }
    function normalizeFixedDocQrRegionRect(rect) {
      const minSize = 1;
      const x = clampFixedDocPreviewPercent(rect.x);
      const y = clampFixedDocPreviewPercent(rect.y);
      const maxW = Math.max(minSize, 100 - x);
      const maxH = Math.max(minSize, 100 - y);
      return {
        x: +x.toFixed(2),
        y: +y.toFixed(2),
        w: +Math.max(minSize, Math.min(maxW, rect.w)).toFixed(2),
        h: +Math.max(minSize, Math.min(maxH, rect.h)).toFixed(2),
      };
    }
    function onFixedDocPreviewPointerDown(event) {
      if (!fixedDocPreviewImage.value) return;
      if (event.target.closest('.fixed-doc-preview-hotspot')) return;
      fixedDocPreviewPanning.value = true;
      fixedDocPreviewPanStart.x = event.clientX;
      fixedDocPreviewPanStart.y = event.clientY;
      fixedDocPreviewPanStart.panX = fixedDocPreviewPanX.value;
      fixedDocPreviewPanStart.panY = fixedDocPreviewPanY.value;
      event.currentTarget.setPointerCapture?.(event.pointerId);
    }
    function onFixedDocPreviewPointerMove(event) {
      if (!fixedDocPreviewPanning.value) return;
      fixedDocPreviewPanX.value = fixedDocPreviewPanStart.panX + (event.clientX - fixedDocPreviewPanStart.x);
      fixedDocPreviewPanY.value = fixedDocPreviewPanStart.panY + (event.clientY - fixedDocPreviewPanStart.y);
    }
    function onFixedDocPreviewPointerUp(event) {
      if (!fixedDocPreviewPanning.value) return;
      fixedDocPreviewPanning.value = false;
      event.currentTarget.releasePointerCapture?.(event.pointerId);
    }
    const fixedDocActiveQrSourceId = ref('');
    const fixedDocPreviewShowQrHotspots = computed(() => (
      fixedDocSetupStep.value === 2
      && fixedDocReadTab.value === 'text'
      && fixedDocReadMode.value === 'qr'
      && !!fixedDocPreviewImage.value
      && fixedDocHasStep1Template.value
      && !fixedDocQrScanActive.value
    ));
